#include <iostream>
using namespace std;
struct Node { int v; Node *l, *r; };
void pre(Node* p) {          // 先序遍历：根 左 右
    if (!p) return;
    cout << p->v << " ";
    pre(p->l);
    pre(p->r);
}
// 中序：左 根 右；后序：左 右 根，把顺序换一下就行

#include <iostream>
#include <queue>
using namespace std;
struct Node { int v; Node *l, *r; };
void bfs(Node* root) {            // 层序遍历 = BFS
    queue<Node*> q;
    q.push(root);
    while (!q.empty()) {
        Node* p = q.front(); q.pop();
        cout << p->v << " ";
        if (p->l) q.push(p->l);
        if (p->r) q.push(p->r);
    }
}

#include <iostream>
using namespace std;
int f[100005];
int main() {
    int n;
    cin >> n;
    f[0] = 1; f[1] = 1;             // 初始值
    for (int i = 2; i <= n; i++)
        f[i] = f[i - 1] + f[i - 2]; // 从 i-1 或 i-2 跳上来
    cout << f[n] << endl;
    return 0;
}

#include <iostream>
#include <stack>
#include <queue>
using namespace std;
int main() {
    stack<int> st;            // 栈：后进先出
    st.push(1); st.push(2);
    cout << st.top() << endl; // 2
    st.pop();
    queue<int> q;             // 队列：先进先出
    q.push(1); q.push(2);
    cout << q.front() << endl; // 1
    return 0;
}
